// Generated by ds-sync (dialog template, Web Components) from Figma "Dialog". Do not edit by hand.
// Visuals come from Figma. Behaviour: WAI-ARIA dialog pattern on a native <dialog> (showModal).
import { LitElement, html, nothing, unsafeCSS } from 'lit';

import { icon } from '../../icons/icon';
import '../Button/ds-button';
import css from './Dialog.css?inline';

export class DsDialog extends LitElement {
  static override styles = [unsafeCSS(':host { display: contents; }'), unsafeCSS(css)];
  static override properties = {
    open: { type: Boolean, reflect: true },
    modal: { type: Boolean, converter: { fromAttribute: (value: string | null) => value !== 'false' } },
    type: { type: String, reflect: true, attribute: "type" },
    size: { type: String, reflect: true, attribute: "size" },
    state: { type: String, reflect: true, attribute: "state" },
    hasCloseButton: { type: Boolean, attribute: "has-close-button" },
    hasSecondaryAction: { type: Boolean, attribute: "has-secondary-action" },
    hasSubtitle: { type: Boolean, attribute: "has-subtitle" },
    scrollableContent: { type: Boolean, attribute: "scrollable-content" },
    titleValue: { type: String, attribute: "title-value" },
    subtitle: { type: String, attribute: "subtitle" },
    bodyContent: { type: String, attribute: "body-content" },
  };

  /** Open */
  declare open: boolean;
  /** Modal (default): focus stays inside, the page behind is inert, and a backdrop shows. modal="false" for an in-page dialog */
  declare modal: boolean;
  /** Figma: Type */
  declare type: "confirmation" | "alert" | "form" | "full-screen" | "side-drawer";
  /** Figma: Size */
  declare size: "small" | "medium" | "large" | "full";
  /** Figma: State */
  declare state: "open" | "loading" | "error";
  /** Figma: Has close button */
  declare hasCloseButton: boolean;
  /** Figma: Has secondary action */
  declare hasSecondaryAction: boolean;
  /** Figma: Has subtitle */
  declare hasSubtitle: boolean;
  /** Figma: Scrollable content */
  declare scrollableContent: boolean;
  /** Figma: Title */
  declare titleValue: string;
  /** Figma: Subtitle */
  declare subtitle: string;
  /** Figma: Body content */
  declare bodyContent: string;

  constructor() {
    super();
    this.open = false;
    this.modal = true;
    this.type = "confirmation";
    this.size = "small";
    this.state = "open";
    this.hasCloseButton = true;
    this.hasSecondaryAction = true;
    this.hasSubtitle = false;
    this.scrollableContent = false;
    this.titleValue = "Dialog title";
    this.subtitle = "Supporting context text";
    this.bodyContent = "Dialog body copy goes here.";
  }

  private get dialog() {
    return this.renderRoot.querySelector('dialog');
  }

  /** Opens or closes the dialog and fires a composed "open-change" event (detail: the new state). */
  setOpen(open: boolean) {
    if (this.open === open) return;
    this.open = open;
    this.dispatchEvent(new CustomEvent('open-change', { detail: open, bubbles: true, composed: true }));
  }

  override updated() {
    const dialog = this.dialog;
    if (!dialog) return;
    if (this.open && !dialog.open) {
      if (this.modal) dialog.showModal();
      else dialog.show();
    } else if (!this.open && dialog.open) dialog.close();
  }

  private onKeyDown(event: KeyboardEvent) {
    // WAI-ARIA dialog: Escape closes it (modal or not).
    if (event.key === 'Escape' && !event.defaultPrevented) {
      event.preventDefault();
      this.setOpen(false);
    }
  }

  override render() {
    return html`<dialog class="root" part="root" role=${this.type === 'alert' ? 'alertdialog' : nothing} aria-labelledby="title" aria-describedby="body" aria-busy=${this.state === 'loading' ? 'true' : nothing} data-type=${this.type} data-size=${this.size} data-state=${this.state}
        @keydown=${this.onKeyDown} @close=${() => this.setOpen(false)}>
        <div class="header">
          <div class="headerTextCol">
            <span class="title" id="title">${this.titleValue}</span>
            ${this.hasSubtitle ? html`<span class="subtitle">${this.subtitle}</span>` : nothing}
          </div>
          ${this.hasCloseButton ? html`<button type="button" class="closeIcon" aria-label="Close" @click=${() => this.setOpen(false)}>${icon("actionClose20")}</button>` : nothing}
        </div>
        ${this.scrollableContent ? html`<span class="dividerTop" aria-hidden="true"></span>` : nothing}
        <div class="body" id="body"><slot>
            <span class="bodyContent">${this.bodyContent}</span>
            <div class="formField">
              <span class="fieldLabel">${(({"full-screen":"Project name"} as Record<string, string>)[this.type] ?? "Full name")}</span>
              <div class="fieldInput">
                <span class="fieldPlaceholder">${(({"full-screen":"Marketing website redesign"} as Record<string, string>)[this.type] ?? "Jordan Lee")}</span>
              </div>
            </div>
            <div class="formField2">
              <span class="fieldLabel2">${(({"full-screen":"Workspace"} as Record<string, string>)[this.type] ?? "Email address")}</span>
              <div class="fieldInput2">
                <span class="fieldPlaceholder2">${(({"full-screen":"Select a workspace"} as Record<string, string>)[this.type] ?? "jordan@company.com")}</span>
              </div>
            </div>
            <div class="errorBanner">
              <span class="errorIcon" aria-hidden="true">${icon("statusError20")}</span>
              <span class="errorText">${"Please correct the errors below and try again."}</span>
            </div>
          </slot></div>
        ${this.scrollableContent ? html`<span class="dividerBottom" aria-hidden="true"></span>` : nothing}
        <div class="footer"><slot name="footer">
            ${this.hasSecondaryAction ? html`<span class="secondaryButton"><ds-button .variant=${"secondary"} .size=${"md"}>${"Cancel"}</ds-button></span>` : nothing}
            <span class="primaryButton"><ds-button .size=${"md"}>${(this.state === "loading" ? "Loading…" : (({"alert":"Got it","form":"Save changes","full-screen":"Create project","side-drawer":"Save"} as Record<string, string>)[this.type] ?? "Confirm"))}</ds-button></span>
          </slot></div>
      </dialog>`;
  }
}

if (!customElements.get('ds-dialog')) customElements.define('ds-dialog', DsDialog);

declare global {
  interface HTMLElementTagNameMap {
    'ds-dialog': DsDialog;
  }
}
